/* fasta — the equivalent-semantics C peer for the tuonelang fasta workload
 * (the Benchmarks Game's fasta): generate the three DNA sequences — ALU
 * repeated for 2N bases, then 3N bases drawn from the IUB code table and 5N
 * from Homo sapiens frequencies, with the benchmark's linear congruential
 * generator — wrapped at 60 bases per line. Instead of writing to stdout,
 * every generated byte (newlines included) is folded into a checksum
 * (sum = (sum * 31 + byte) % 1000003); the exit byte is sum % 256. */
#define N 1000000
#define LINE 60
#define IM 139968
#define IA 3877
#define IC 29573

static const char ALU[] =
    "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG"
    "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGA"
    "CCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAAT"
    "ACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCA"
    "GCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGGG"
    "AGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCC"
    "AGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

static long long sum = 0;
static long long last = 42;

static void emit(long long byte) { sum = (sum * 31 + byte) % 1000003; }

static double random_unit(void) {
    last = (last * IA + IC) % IM;
    return (double)last / (double)IM;
}

static void repeat(long long n) {
    long long len = (long long)(sizeof ALU - 1), at = 0, col = 0;
    for (long long i = 0; i < n; i++) {
        emit(ALU[at]);
        at = at + 1;
        if (at == len) at = 0;
        col = col + 1;
        if (col == LINE) { emit('\n'); col = 0; }
    }
    if (col > 0) emit('\n');
}

static void random_seq(const char *codes, const double *cumulative, int count, long long n) {
    long long col = 0;
    for (long long i = 0; i < n; i++) {
        double r = random_unit();
        int k = 0;
        while (k < count - 1 && r >= cumulative[k]) k = k + 1;
        emit(codes[k]);
        col = col + 1;
        if (col == LINE) { emit('\n'); col = 0; }
    }
    if (col > 0) emit('\n');
}

static void cumulate(const double *p, double *out, int count) {
    double acc = 0.0;
    for (int i = 0; i < count; i++) { acc = acc + p[i]; out[i] = acc; }
}

int main(void) {
    static const char iub_codes[] = "acgtBDHKMNRSVWY";
    static const double iub_p[15] = {0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02,
                                     0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02};
    static const char homo_codes[] = "acgt";
    static const double homo_p[4] = {0.3029549426680, 0.1979883004921,
                                     0.1975473066391, 0.3015094502008};
    double iub_c[15], homo_c[4];
    cumulate(iub_p, iub_c, 15);
    cumulate(homo_p, homo_c, 4);
    repeat(2 * N);
    random_seq(iub_codes, iub_c, 15, 3 * N);
    random_seq(homo_codes, homo_c, 4, 5 * N);
    return (int)(sum % 256);
}
